package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;
import static org.jlinalg.cli.SpectralAnnotationRequest.require;

/** Complete original-input capture and portable full metadata replay. No MS fitting occurs. */
final class SpectralAnnotationBundle {
    static final String PROFILE="native-explicit-spectral-fragment-annotations-v1";
    static final String ACTION="Required action: read WARNINGS.md, OUTPUT-AUDIT.json and ROWS.jsonl. Require COMPLETED.json and spectral-library-annotations --verify with the exact producing JAR before using the prepared table. Preparation does not admit an MS analysis. Supply a separately permitted upstream runtime and appropriate references, or skip dependent analysis when prerequisites are unavailable or forbidden. FAIL2 admits no complete preparation: preserve the attempt, correct the named source/syntax/capacity problem and retry NEW paths. Do not guess charges, discard unsupported rows, replace original values or refresh old seals.";
    static final class Unavailable extends IOException{private static final long serialVersionUID=1L;Unavailable(String message){super(message);}}
    private SpectralAnnotationBundle() { }
    static Pin producer()throws IOException{
        try{
            Path p=Path.of(SpectralAnnotationBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();
            if(!p.getFileName().toString().endsWith(".jar"))throw new Unavailable("Build and retain the complete source-built executable JAR; a class directory is not an exact-producer capture runtime");
            return pin(p,1000000000L,()->{});
        }catch(java.net.URISyntaxException|NullPointerException e){throw new Unavailable("The exact producing source-built JAR is unavailable; skip dependent preparation until restored");}
    }
    static Runnable bounded(SpectralAnnotationRequest.Spec s,Runnable cancellation){long start=System.nanoTime();return()->{cancellation.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-start)/1000000>s.capacity().wallMillis())throw new IllegalStateException("Spectral annotation cooperative wall limit/cancellation; no complete preparation");};}
    static Path capture(Path supplied,SpectralAnnotationRequest.Spec s,Runnable cancellation)throws IOException{
        Path root=supplied.toAbsolutePath().normalize();require(supplied.toAbsolutePath().equals(root)&&root.getParent()!=null,"Require a NEW canonical preparation path");directory(root.getParent());require(!Files.exists(root,LinkOption.NOFOLLOW_LINKS),"Preparation path exists; use a NEW path");
        Path original=Path.of(s.file());if(!Files.exists(original,LinkOption.NOFOLLOW_LINKS)||!Files.isReadable(original))throw new Unavailable("Complete permitted source library is missing or unreadable: "+s.file());
        Runnable check=bounded(s,cancellation);Pin source=pin(original,s.capacity().inputBytes(),check),producer=producer();boolean created=false;String stage="CREATE_NEW_CAPTURE";
        try{
            Files.createDirectory(root);created=true;Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("outputs"));writeJson(root.resolve("INCOMPLETE.json"),Map.of("preparation_admitted",false));writeJson(root.resolve("request.json"),s.value());Files.writeString(root.resolve("WARNINGS.md"),warnings(),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            stage="CAPTURE_COMPLETE_ORIGINAL_INPUT";Files.copy(original,root.resolve("inputs/library.tsv"));require(source.equals(pin(root.resolve("inputs/library.tsv"),s.capacity().inputBytes(),check))&&source.equals(pin(original,s.capacity().inputBytes(),check)),"Source library changed during complete capture");writeJson(root.resolve("source-inputs.json"),Map.of("original",s.file(),"pin",source,"complete_original_bytes",true));
            stage="EXPAND_EXPLICIT_ANNOTATIONS";writeJson(root.resolve("OUTPUT-AUDIT.json"),SpectralAnnotationCompute.run(root,s,false,check));require(source.equals(pin(original,s.capacity().inputBytes(),check))&&producer.equals(producer()),"Original source or producer changed");
            stage="FINALIZE_AND_REPLAY";var files=files(root,s,check);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile",PROFILE,"producer",producer,"files",files,"preparation_admitted",true,"raw_MS_analysis_admitted",false));writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_NATIVE_SPECTRAL_ANNOTATION_PREPARATION","manifest",pin(root.resolve("manifest.json"),1048576,check),"preparation_admitted",true,"raw_MS_analysis_admitted",false));verify(root,true,check);require(source.equals(pin(original,s.capacity().inputBytes(),check))&&producer.equals(producer()),"Source library or producer changed before final admission");Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error error){if(created)failure(root,stage,error);throw error;}
    }
    static void verify(Path supplied,boolean precommit,Runnable cancellation)throws IOException{
        Path root=supplied.toAbsolutePath().normalize();directory(root);require(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS)&&Files.exists(root.resolve("INCOMPLETE.json"),LinkOption.NOFOLLOW_LINKS)==precommit,"Failed/incomplete spectral annotation attempt is not admitted");
        var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"schema_version","status","manifest","preparation_admitted","raw_MS_analysis_admitted");integer(done.get("schema_version"),1,1);require("COMPLETE_NATIVE_SPECTRAL_ANNOTATION_PREPARATION".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("preparation_admitted"))&&Boolean.FALSE.equals(done.get("raw_MS_analysis_admitted")),"Missing or expanded preparation admission");
        Pin m=pin(root.resolve("manifest.json"),1048576,cancellation);require(m.equals(fingerprint(done.get("manifest"),1048576)),"Saved manifest changed");var saved=object(json(root.resolve("manifest.json"),1048576));keys(saved,"schema_version","profile","producer","files","preparation_admitted","raw_MS_analysis_admitted");integer(saved.get("schema_version"),1,1);require(PROFILE.equals(saved.get("profile"))&&Boolean.TRUE.equals(saved.get("preparation_admitted"))&&Boolean.FALSE.equals(saved.get("raw_MS_analysis_admitted")),"Different or expanded spectral preparation contract");require(producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Restore exact producing JAR; do not reseal a different executable");
        var s=SpectralAnnotationRequest.read(root.resolve("request.json"),false);Runnable check=bounded(s,cancellation);inventory(root,s,saved.get("files"),precommit,check);
        var source=object(json(root.resolve("source-inputs.json"),1048576));keys(source,"original","pin","complete_original_bytes");require(s.file().equals(source.get("original"))&&Boolean.TRUE.equals(source.get("complete_original_bytes"))&&pin(root.resolve("inputs/library.tsv"),s.capacity().inputBytes(),check).equals(fingerprint(source.get("pin"),s.capacity().inputBytes())),"Complete original source declaration/bytes differ");
        require(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings()),"Saved warnings/actions differ");require(NextflowJson.json(SpectralAnnotationCompute.run(root,s,true,check)).equals(NextflowJson.json(json(root.resolve("OUTPUT-AUDIT.json"),1048576))),"Saved complete annotation audit differs");inventory(root,s,saved.get("files"),precommit,check);require(m.equals(pin(root.resolve("manifest.json"),1048576,check))&&producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Manifest or producer changed during full replay");
    }
    static Map<String,Object> files(Path root,SpectralAnnotationRequest.Spec s,Runnable check)throws IOException{
        var files=new TreeMap<String,Object>();long reserve=16777216L,total=Math.addExact(Math.addExact(s.capacity().inputBytes(),s.capacity().outputBytes()),reserve),generated=0;
        for(var row:tree(root,32,total,Math.max(s.capacity().inputBytes(),s.capacity().outputBytes())+reserve,check).entrySet()){
            require(row.getValue().kind().equals("file"),"Linked preparation member refused");Pin p=row.getValue().pin();if(!row.getKey().equals("inputs/library.tsv")){generated=Math.addExact(generated,p.bytes());require(generated<=s.capacity().outputBytes()+reserve,"Complete generated preparation exceeds output capacity plus16MiB metadata reserve");}files.put(row.getKey(),Map.of("bytes",p.bytes(),"sha256",p.sha256()));
        }return files;
    }
    private static void inventory(Path root,SpectralAnnotationRequest.Spec s,Object declared,boolean precommit,Runnable check)throws IOException{
        var directories=new HashSet<>(Set.of("","inputs","outputs"));try(var paths=Files.walk(root)){
            var all=paths.limit(65).toList();require(all.size()<=64,"Preparation namespace exceeds bounded file/directory capacity");
            for(Path p:all){check.run();if(Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))require(directories.remove(root.relativize(p).toString().replace('\\','/')),"Extra preparation directory");}
        }require(directories.isEmpty(),"Missing preparation directory");
        var actual=files(root,s,check);var expected=new HashSet<>(Set.of("request.json","WARNINGS.md","inputs/library.tsv","source-inputs.json","ROWS.jsonl","outputs/library.tsv","OUTPUT-AUDIT.json","manifest.json","COMPLETED.json"));if(precommit)expected.add("INCOMPLETE.json");require(actual.keySet().equals(expected),"Missing/extra file in complete preparation namespace");actual.remove("manifest.json");actual.remove("COMPLETED.json");actual.remove("INCOMPLETE.json");require(NextflowJson.json(actual).equals(NextflowJson.json(declared)),"Complete saved preparation byte population differs");
    }
    private static void failure(Path root,String stage,Throwable error){try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("FAILURE.json")))writeJson(root.resolve("FAILURE.json"),Map.of("status","FAIL2_NO_COMPLETE_SPECTRAL_PREPARATION","stage",stage,"error",error.toString(),"required_action",ACTION,"preparation_admitted",false));}catch(IOException suppressed){error.addSuppressed(suppressed);}}
    static String warnings(){return "SPECTRAL LIBRARY ANNOTATIONS: WARNINGS AND REQUIRED ACTION\n\nThis native command extracts explicit bN^Z/yN^Z fragment annotations. It adds FragmentCharge, FragmentType, FragmentSeriesNumber and FragmentLossType; it does not match masses, guess charge1 or alter original masses, intensities, sequences, identities, retention times, ion mobility, field values or row order. The supported grammar contains unshifted b/y ions; other series, neutral-loss syntax, missing/ambiguous values and leading zeros fail the complete preparation. Already annotated/colliding columns are refused rather than overwritten.\n\nSupply uncompressed literal UTF-8 TSV with distinct original headers, at most1020 columns and1Mi characters per record. Quoting is literal. Blank/malformed records and invalid UTF-8 fail; no record is dropped. Generated tables normalize CR/CRLF record endings to LF and remove an optional header BOM; the exact complete original bytes remain in inputs/library.tsv. Every original non-header record has a row ledger. Original scientific values are copied as strings; this preparation does not validate their biological/physical interpretation. Declared row, byte, charge and cooperative time/cancellation limits are complete-population bounds, not JVM heap guarantees. Output capacity covers both the expanded table and ledger.\n\nNo original DIA-NN or other runtime is executed, downloaded or installed. A prepared table does not admit raw-MS identification, quantification, FDR, MBR, reference annotation or a paper reproduction. Run the appropriate separately permitted upstream workflow and inspect its original warnings/results; skip dependent analysis when software, references, licences or installation permissions are unavailable. Do not infer a reported software version or reference edition.\n\nSaved verification checks the complete file/directory population and exact producing JAR, then replays every source cell and annotation and compares both generated files byte for byte. Original host paths are retained as provenance and never accessed during saved replay. Keep the exact producer and inputs; hashes establish integrity, not authenticity or scientific validity.\n\n"+ACTION+"\n";}
}
